// It returns [BadParam] for a bar value that is not finite.
func (sp *KSTEXTStream) Peek(inReal float64) (float64, float64, error) {
	if inReal-inReal != 0 {
		return 0, 0, BadParam
	}
	var cur_kstBuffer float64
	var cur_tempBuffer float64
	var cur_outKSTSignal float64
	var cur_outKST float64
	var subErr error
	cur_kstBuffer, subErr = sp.sub0.Peek(inReal)
	if subErr != nil {
		return 0, 0, subErr
	}
	cur_kstBuffer, subErr = sp.sub1.Peek(cur_kstBuffer)
	if subErr != nil {
		return 0, 0, subErr
	}
	cur_tempBuffer, subErr = sp.sub2.Peek(inReal)
	if subErr != nil {
		return 0, 0, subErr
	}
	cur_tempBuffer, subErr = sp.sub3.Peek(cur_tempBuffer)
	if subErr != nil {
		return 0, 0, subErr
	}
	cur_kstBuffer = math.FMA(2.0, cur_tempBuffer, cur_kstBuffer)
	cur_tempBuffer, subErr = sp.sub4.Peek(inReal)
	if subErr != nil {
		return 0, 0, subErr
	}
	cur_tempBuffer, subErr = sp.sub5.Peek(cur_tempBuffer)
	if subErr != nil {
		return 0, 0, subErr
	}
	cur_kstBuffer = math.FMA(3.0, cur_tempBuffer, cur_kstBuffer)
	cur_tempBuffer, subErr = sp.sub6.Peek(inReal)
	if subErr != nil {
		return 0, 0, subErr
	}
	cur_tempBuffer, subErr = sp.sub7.Peek(cur_tempBuffer)
	if subErr != nil {
		return 0, 0, subErr
	}
	cur_kstBuffer = math.FMA(4.0, cur_tempBuffer, cur_kstBuffer)
	cur_outKSTSignal, subErr = sp.sub8.Peek(cur_kstBuffer)
	if subErr != nil {
		return 0, 0, subErr
	}
	cur_outKST = cur_kstBuffer
	return cur_outKST, cur_outKSTSignal, nil
}

// Value returns the outputs at the last bar of OutRange, in Update's order;
// Peek does not change them.
func (sp *KSTEXTStream) Value() (float64, float64) {
	return sp.cur_outKST, sp.cur_outKSTSignal
}

// Clone returns an independent copy of the stream at the same bar: the two
// evolve separately and share only the [Core].
func (sp *KSTEXTStream) Clone() *KSTEXTStream {
	cl := *sp
	cl.sub0 = sp.sub0.Clone()
	cl.sub1 = sp.sub1.Clone()
	cl.sub2 = sp.sub2.Clone()
	cl.sub3 = sp.sub3.Clone()
	cl.sub4 = sp.sub4.Clone()
	cl.sub5 = sp.sub5.Clone()
	cl.sub6 = sp.sub6.Clone()
	cl.sub7 = sp.sub7.Clone()
	cl.sub8 = sp.sub8.Clone()
	return &cl
}

func (c *Core) kstextOpenImpl(sp *KSTEXTStream, inReal []float64, startIdx, optInROC1Period, optInROC2Period, optInROC3Period, optInROC4Period, optInMA1Period, optInMA2Period, optInMA3Period, optInMA4Period, optInSignalPeriod, optInROCMAType, optInSignalMAType int32, outBegIdx, outNBElement *int32, outKST, outKSTSignal []float64, outStride int32) RetCode {
	var kstBuffer []float64
	var tempBuffer []float64
	var lookbackTotal int32
	var lookbackSignal int32
	var lookbackMA int32
	var sigStart int32
	var lookbackMA1 int32
	var lookbackMA2 int32
	var lookbackMA3 int32
	var lookbackMA4 int32
	var tempInteger int32
	var tempBegIdx int32
	var rocNb int32
	var kstNb int32
	var legNb int32
	var sigNb int32
	var i int32
	if len(inReal) > IndexMax+1 {
		return OutOfRangeEndIndex
	}
	historyLen := int32(len(inReal))
	endIdx := historyLen - 1
	if optInROC1Period == IntegerDefault {
		optInROC1Period = 10
	} else if optInROC1Period < 1 || optInROC1Period > 100000 {
		return BadParam
	}
	if optInROC2Period == IntegerDefault {
		optInROC2Period = 15
	} else if optInROC2Period < 1 || optInROC2Period > 100000 {
		return BadParam
	}
	if optInROC3Period == IntegerDefault {
		optInROC3Period = 20
	} else if optInROC3Period < 1 || optInROC3Period > 100000 {
		return BadParam
	}
	if optInROC4Period == IntegerDefault {
		optInROC4Period = 30
	} else if optInROC4Period < 1 || optInROC4Period > 100000 {
		return BadParam
	}
	if optInMA1Period == IntegerDefault {
		optInMA1Period = 10
	} else if optInMA1Period < 1 || optInMA1Period > 100000 {
		return BadParam
	}
	if optInMA2Period == IntegerDefault {
		optInMA2Period = 10
	} else if optInMA2Period < 1 || optInMA2Period > 100000 {
		return BadParam
	}
	if optInMA3Period == IntegerDefault {
		optInMA3Period = 10
	} else if optInMA3Period < 1 || optInMA3Period > 100000 {
		return BadParam
	}
	if optInMA4Period == IntegerDefault {
		optInMA4Period = 15
	} else if optInMA4Period < 1 || optInMA4Period > 100000 {
		return BadParam
	}
	if optInSignalPeriod == IntegerDefault {
		optInSignalPeriod = 9
	} else if optInSignalPeriod < 1 || optInSignalPeriod > 100000 {
		return BadParam
	}
	if optInROCMAType == IntegerDefault || optInROCMAType == int32(MATypeDEFAULT) {
		optInROCMAType = int32(MATypeSMA)
	} else if optInROCMAType < MATypeMin || optInROCMAType > MATypeMax {
		return BadParam
	}
	if optInSignalMAType == IntegerDefault || optInSignalMAType == int32(MATypeDEFAULT) {
		optInSignalMAType = int32(MATypeSMA)
	} else if optInSignalMAType < MATypeMin || optInSignalMAType > MATypeMax {
		return BadParam
	}
	if startIdx >= historyLen {
		*outBegIdx = 0
		*outNBElement = 0
		return InsufficientHistory
	}
	if historyLen < c.kstextLookback(optInROC1Period, optInROC2Period, optInROC3Period, optInROC4Period, optInMA1Period, optInMA2Period, optInMA3Period, optInMA4Period, optInSignalPeriod, optInROCMAType, optInSignalMAType)+1 {
		return InsufficientHistory
	}
	var sc_outKST []float64
	if outStride == 1 {
		sc_outKST = outKST
	} else {
		sc_outKST = make([]float64, historyLen)
	}
	var sc_outKSTSignal []float64
	if outStride == 1 {
		sc_outKSTSignal = outKSTSignal
	} else {
		sc_outKSTSignal = make([]float64, historyLen)
	}
	lagNb0 := int32(0)
	lagNb1 := int32(0)
	lagNb2 := int32(0)
	lagNb3 := int32(0)
	lagNb4 := int32(0)
	*outBegIdx = 0
	*outNBElement = 0
	lookbackSignal = c.maLookback(optInSignalPeriod, optInSignalMAType)
	lookbackMA1 = c.maLookback(optInMA1Period, optInROCMAType)
	lookbackMA2 = c.maLookback(optInMA2Period, optInROCMAType)
	lookbackMA3 = c.maLookback(optInMA3Period, optInROCMAType)
	lookbackMA4 = c.maLookback(optInMA4Period, optInROCMAType)
	lookbackTotal = optInROC1Period + lookbackMA1
	tempInteger = optInROC2Period + lookbackMA2
	if tempInteger > lookbackTotal {
		lookbackTotal = tempInteger
	}
	tempInteger = optInROC3Period + lookbackMA3
	if tempInteger > lookbackTotal {
		lookbackTotal = tempInteger
	}
	tempInteger = optInROC4Period + lookbackMA4
	if tempInteger > lookbackTotal {
		lookbackTotal = tempInteger
	}
	lookbackTotal += lookbackSignal
	if startIdx < lookbackTotal {
		startIdx = lookbackTotal
	}
	if startIdx > endIdx {
		return InsufficientHistory
	}
	sigStart = startIdx - lookbackSignal
	lookbackMA = lookbackMA1
	if lookbackMA2 > lookbackMA {
		lookbackMA = lookbackMA2
	}
	if lookbackMA3 > lookbackMA {
		lookbackMA = lookbackMA3
	}
	if lookbackMA4 > lookbackMA {
		lookbackMA = lookbackMA4
	}
	tempInteger = endIdx - sigStart + 1 + lookbackMA
	kstBuffer = make([]float64, tempInteger)
	tempBuffer = make([]float64, tempInteger)
	sub0, _E0 := c.rocOpenAndFillInternal(inReal, sigStart-lookbackMA1, optInROC1Period, &tempBegIdx, &rocNb, kstBuffer)
	if _E0 != nil {
		return _E0.(RetCode)
	}
	sub1, _E1 := c.maOpenInternal(kstBuffer[:rocNb-1+1], 0, optInMA1Period, optInROCMAType)
	if _E1 != nil {
		return _E1.(RetCode)
	}
	_X9, _E9 := c.MA(0, int(rocNb-1), kstBuffer, int(optInMA1Period), MAType(optInROCMAType), kstBuffer)
	if _E9 != nil {
		return _E9.(RetCode)
	}
	tempBegIdx = int32(_X9.BegIdx)
	kstNb = int32(_X9.NBElement)
	sub2, _E2 := c.rocOpenAndFillInternal(inReal, sigStart-lookbackMA2, optInROC2Period, &tempBegIdx, &rocNb, tempBuffer)
	if _E2 != nil {
		return _E2.(RetCode)
	}
	sub3, _E3 := c.maOpenInternal(tempBuffer[:rocNb-1+1], 0, optInMA2Period, optInROCMAType)
	if _E3 != nil {
		return _E3.(RetCode)
	}
	_X10, _E10 := c.MA(0, int(rocNb-1), tempBuffer, int(optInMA2Period), MAType(optInROCMAType), tempBuffer)
	if _E10 != nil {
		return _E10.(RetCode)
	}
	tempBegIdx = int32(_X10.BegIdx)
	legNb = int32(_X10.NBElement)
	lagNb0 = legNb
	if kstNb < 1 {
		return InsufficientHistory
	}
	if lagNb0-kstNb != 0 {
		return InternalError
	}
	for i = 0; i < kstNb; i += 1 {
		kstBuffer[i] = math.FMA(2.0, tempBuffer[i], kstBuffer[i])
	}
	sub4, _E4 := c.rocOpenAndFillInternal(inReal, sigStart-lookbackMA3, optInROC3Period, &tempBegIdx, &rocNb, tempBuffer)
	if _E4 != nil {
		return _E4.(RetCode)
	}
	sub5, _E5 := c.maOpenInternal(tempBuffer[:rocNb-1+1], 0, optInMA3Period, optInROCMAType)
	if _E5 != nil {
		return _E5.(RetCode)
	}
	_X11, _E11 := c.MA(0, int(rocNb-1), tempBuffer, int(optInMA3Period), MAType(optInROCMAType), tempBuffer)
	if _E11 != nil {
		return _E11.(RetCode)
	}
	tempBegIdx = int32(_X11.BegIdx)
	legNb = int32(_X11.NBElement)
	lagNb1 = legNb
	if kstNb < 1 {
		return InsufficientHistory
	}
	if lagNb1-kstNb != 0 {
		return InternalError
	}
	for i = 0; i < kstNb; i += 1 {
		kstBuffer[i] = math.FMA(3.0, tempBuffer[i], kstBuffer[i])
	}
	sub6, _E6 := c.rocOpenAndFillInternal(inReal, sigStart-lookbackMA4, optInROC4Period, &tempBegIdx, &rocNb, tempBuffer)
	if _E6 != nil {
		return _E6.(RetCode)
	}
	sub7, _E7 := c.maOpenInternal(tempBuffer[:rocNb-1+1], 0, optInMA4Period, optInROCMAType)
	if _E7 != nil {
		return _E7.(RetCode)
	}
	_X12, _E12 := c.MA(0, int(rocNb-1), tempBuffer, int(optInMA4Period), MAType(optInROCMAType), tempBuffer)
	if _E12 != nil {
		return _E12.(RetCode)
	}
	tempBegIdx = int32(_X12.BegIdx)
	legNb = int32(_X12.NBElement)
	lagNb2 = legNb
	lagNb3 = kstNb
	if kstNb < 1 {
		return InsufficientHistory
	}
	if lagNb2-kstNb != 0 {
		return InternalError
	}
	for i = 0; i < kstNb; i += 1 {
		kstBuffer[i] = math.FMA(4.0, tempBuffer[i], kstBuffer[i])
	}
	lagNb4 = endIdx - startIdx + 1
	if endIdx-startIdx < 0 {
		return InsufficientHistory
	}
	if lagNb3-lookbackSignal-(endIdx-startIdx+1) != 0 {
		return InternalError
	}
	copy(sc_outKST, kstBuffer[lookbackSignal:lookbackSignal+(endIdx-startIdx+1)])
	sub8, _E8 := c.maOpenAndFillInternal(kstBuffer[:kstNb-1+1], 0, optInSignalPeriod, optInSignalMAType, &tempBegIdx, &sigNb, sc_outKSTSignal)
	if _E8 != nil {
		return _E8.(RetCode)
	}
	*outBegIdx = startIdx
	*outNBElement = sigNb
	if *outNBElement < 1 {
		return InsufficientHistory
	}
	if lagNb4-*outNBElement != 0 {
		return InternalError
	}
	sp.optInROC1Period = optInROC1Period
	sp.optInROC2Period = optInROC2Period
	sp.optInROC3Period = optInROC3Period
	sp.optInROC4Period = optInROC4Period
	sp.optInMA1Period = optInMA1Period
	sp.optInMA2Period = optInMA2Period
	sp.optInMA3Period = optInMA3Period
	sp.optInMA4Period = optInMA4Period
	sp.optInSignalPeriod = optInSignalPeriod
	sp.optInROCMAType = optInROCMAType
	sp.optInSignalMAType = optInSignalMAType
	sp.sub0 = sub0
	sp.sub1 = sub1
	sp.sub2 = sub2
	sp.sub3 = sub3
	sp.sub4 = sub4
	sp.sub5 = sub5
	sp.sub6 = sub6
	sp.sub7 = sub7
	sp.sub8 = sub8
	sp.cur_outKST = sc_outKST[*outNBElement-1]
	sp.cur_outKSTSignal = sc_outKSTSignal[*outNBElement-1]
	return Success
}

func (c *Core) kstextOpenAndFillInternal(inReal []float64, startIdx, optInROC1Period, optInROC2Period, optInROC3Period, optInROC4Period, optInMA1Period, optInMA2Period, optInMA3Period, optInMA4Period, optInSignalPeriod, optInROCMAType, optInSignalMAType int32, outBegIdx, outNBElement *int32, outKST, outKSTSignal []float64) (*KSTEXTStream, error) {
	sp := &KSTEXTStream{core: c}
	if retCode := c.kstextOpenImpl(sp, inReal, startIdx, optInROC1Period, optInROC2Period, optInROC3Period, optInROC4Period, optInMA1Period, optInMA2Period, optInMA3Period, optInMA4Period, optInSignalPeriod, optInROCMAType, optInSignalMAType, outBegIdx, outNBElement, outKST, outKSTSignal, 1); retCode != Success {
		return nil, retCode
	}
	sp.outRangeBegIdx = int(*outBegIdx)
	sp.outRangeCount = int(*outNBElement)
	return sp, nil
}

func (c *Core) kstextOpenInternal(inReal []float64, startIdx, optInROC1Period, optInROC2Period, optInROC3Period, optInROC4Period, optInMA1Period, optInMA2Period, optInMA3Period, optInMA4Period, optInSignalPeriod, optInROCMAType, optInSignalMAType int32) (*KSTEXTStream, error) {
	sp := &KSTEXTStream{core: c}
	var outBegIdx, outNBElement int32
	var sink_outKST [1]float64
	var sink_outKSTSignal [1]float64
	if retCode := c.kstextOpenImpl(sp, inReal, startIdx, optInROC1Period, optInROC2Period, optInROC3Period, optInROC4Period, optInMA1Period, optInMA2Period, optInMA3Period, optInMA4Period, optInSignalPeriod, optInROCMAType, optInSignalMAType, &outBegIdx, &outNBElement, sink_outKST[:], sink_outKSTSignal[:], 0); retCode != Success {
		return nil, retCode
	}
	sp.outRangeBegIdx = int(outBegIdx)
	sp.outRangeCount = int(outNBElement)
	return sp, nil
}

// KSTEXTOpen opens a live [KSTEXTStream] on a warm-up history, oldest bar
// first, and returns it with its values at the last history bar (outKST and
// outKSTSignal), the values [Core.KSTEXT] writes there.
//
// inReal is the history; the parameters are those of [Core.KSTEXT].
//
// The error is [InsufficientHistory] for a history of at most
// [Core.KSTEXTLookback] bars, [OutOfRangeEndIndex] for one longer than
// [IndexMax]+1 bars, and [BadParam] for a parameter out of range.
func (c *Core) KSTEXTOpen(inReal []float64, optInROC1Period, optInROC2Period, optInROC3Period, optInROC4Period, optInMA1Period, optInMA2Period, optInMA3Period, optInMA4Period, optInSignalPeriod int, optInROCMAType, optInSignalMAType MAType) (*KSTEXTStream, float64, float64, error) {
	if !fitsInt32(optInROC1Period) {
		return nil, 0, 0, BadParam
	}
	if !fitsInt32(optInROC2Period) {
		return nil, 0, 0, BadParam
	}
	if !fitsInt32(optInROC3Period) {
		return nil, 0, 0, BadParam
	}
	if !fitsInt32(optInROC4Period) {
		return nil, 0, 0, BadParam
	}
	if !fitsInt32(optInMA1Period) {
		return nil, 0, 0, BadParam
	}
	if !fitsInt32(optInMA2Period) {
		return nil, 0, 0, BadParam
	}
	if !fitsInt32(optInMA3Period) {
		return nil, 0, 0, BadParam
	}
	if !fitsInt32(optInMA4Period) {
		return nil, 0, 0, BadParam
	}
	if !fitsInt32(optInSignalPeriod) {
		return nil, 0, 0, BadParam
	}
	sp, err := c.kstextOpenInternal(inReal, 0, int32(optInROC1Period), int32(optInROC2Period), int32(optInROC3Period), int32(optInROC4Period), int32(optInMA1Period), int32(optInMA2Period), int32(optInMA3Period), int32(optInMA4Period), int32(optInSignalPeriod), int32(optInROCMAType), int32(optInSignalMAType))
	if err != nil {
		return nil, 0, 0, err
	}
	return sp, sp.cur_outKST, sp.cur_outKSTSignal, nil
}

// KSTEXTOpenAndFill opens a stream as [Core.KSTEXTOpen] does and also writes
// the outputs over the whole history, as [Core.KSTEXT] writes them for bars 0
// through len(inReal)-1, returning that range.
//
// Each output must hold len(inReal) minus [Core.KSTEXTLookback] values and
// share no memory with an input or another output.
//
// The errors are those of [Core.KSTEXTOpen], and [BadParam] for an output that
// is empty, too short or sharing memory. A slice whose capacity a three-index
// expression cut, as slices.Clip does, can escape the sharing check.
func (c *Core) KSTEXTOpenAndFill(inReal []float64, optInROC1Period, optInROC2Period, optInROC3Period, optInROC4Period, optInMA1Period, optInMA2Period, optInMA3Period, optInMA4Period, optInSignalPeriod int, optInROCMAType, optInSignalMAType MAType, outKST, outKSTSignal []float64) (*KSTEXTStream, OutRange, error) {
	if !fitsInt32(optInROC1Period) {
		return nil, OutRange{}, BadParam
	}
	if !fitsInt32(optInROC2Period) {
		return nil, OutRange{}, BadParam
	}
	if !fitsInt32(optInROC3Period) {
		return nil, OutRange{}, BadParam
	}
	if !fitsInt32(optInROC4Period) {
		return nil, OutRange{}, BadParam
	}
	if !fitsInt32(optInMA1Period) {
		return nil, OutRange{}, BadParam
	}
	if !fitsInt32(optInMA2Period) {
		return nil, OutRange{}, BadParam
	}
	if !fitsInt32(optInMA3Period) {
		return nil, OutRange{}, BadParam
	}
	if !fitsInt32(optInMA4Period) {
		return nil, OutRange{}, BadParam
	}
	if !fitsInt32(optInSignalPeriod) {
		return nil, OutRange{}, BadParam
	}
	if len(inReal) > IndexMax+1 {
		return nil, OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.kstextLookback(int32(optInROC1Period), int32(optInROC2Period), int32(optInROC3Period), int32(optInROC4Period), int32(optInMA1Period), int32(optInMA2Period), int32(optInMA3Period), int32(optInMA4Period), int32(optInSignalPeriod), int32(optInROCMAType), int32(optInSignalMAType)))
	if lookback < 0 {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inReal)-lookback, 0)
	if len(outKST) == 0 || len(outKST) < outLen {
		return nil, OutRange{}, BadParam
	}
	if len(outKSTSignal) == 0 || len(outKSTSignal) < outLen {
		return nil, OutRange{}, BadParam
	}
	if sameStart(outKST, inReal) || sameStart(outKSTSignal, inReal) || sameStart(outKST, outKSTSignal) {
		return nil, OutRange{}, BadParam
	}
	if outLen > 0 && (overlaps(outKST, inReal) || overlaps(outKSTSignal, inReal) || overlaps(outKST, outKSTSignal)) {
		return nil, OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	sp, err := c.kstextOpenAndFillInternal(inReal, 0, int32(optInROC1Period), int32(optInROC2Period), int32(optInROC3Period), int32(optInROC4Period), int32(optInMA1Period), int32(optInMA2Period), int32(optInMA3Period), int32(optInMA4Period), int32(optInSignalPeriod), int32(optInROCMAType), int32(optInSignalMAType), &outBegIdx, &outNBElement, outKST, outKSTSignal)
	if err != nil {
		return nil, OutRange{}, err
	}
	return sp, OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}
